mapper.select:
select

from profile_meta_dataset d
left join profile_meta_user u on d.owner = u.user_id
where 1 = 1

  and d.status = #{status,jdbcType=INTEGER}


  and d.dataset_id = #{datasetId,jdbcType=VARCHAR}


  and d.dataset_name = #{datasetName,jdbcType=VARCHAR}


  and d.dataset_type = #{datasetType,jdbcType=INTEGER}


  and d.dataset_desc = #{datasetDesc,jdbcType=VARCHAR}


  and d.source_type = #{sourceType,jdbcType=INTEGER}


  and d.datasource_id = #{datasourceId,jdbcType=VARCHAR}


  and d.table_name = #{tableName,jdbcType=VARCHAR}


  and d.partition_field = #{partitionField,jdbcType=VARCHAR}


  and d.partition_format = #{partitionFormat,jdbcType=VARCHAR}


  and d.entity_id = #{entityId,jdbcType=VARCHAR}


  and d.entity_field = #{entityField,jdbcType=VARCHAR}


  and d.owner = #{owner,jdbcType=VARCHAR}


  and d.creator = #{creator,jdbcType=VARCHAR}


  and d.modifier = #{modifier,jdbcType=VARCHAR}


  and d.gmt_create = #{gmtCreate,jdbcType=TIMESTAMP}


  and d.gmt_modified = #{gmtModified,jdbcType=TIMESTAMP}
